/** a free list of blocks of one size: what is made and dropped by the million (cells, lists, objects) is not asked of malloc each time */
template <size_t Size> struct Pool {
  static inline void* free_ = nullptr;
  static void* take() {
    if (free_) { void* p = free_; free_ = *static_cast<void**>(p); return p; }
    return ::operator new(Size < sizeof(void*) ? sizeof(void*) : Size);
  }
  static void give(void* p) { *static_cast<void**>(p) = free_; free_ = p; }
};
template <class T> struct Pooled : Heap {
  static void* operator new(size_t n) { return n == sizeof(T) ? Pool<sizeof(T)>::take() : ::operator new(n); }
  static void operator delete(void* p, size_t n) { if (n == sizeof(T)) Pool<sizeof(T)>::give(p); else ::operator delete(p); }
};

