inline bool truthy(const Value& x) {
  switch (x.t) {
    case Value::NIL: return false;
    case Value::BOOL: return x.b;
    case Value::NUM: return x.n != 0 && !std::isnan(x.n);
    case Value::STR: return !x.as<Str>()->s.empty();
    default: return true;
  }
}
