inline double num(const Value& x) {
  switch (x.t) {
    case Value::NUM: return x.n;
    case Value::NIL: return 0.0;
    case Value::BOOL: return x.b ? 1.0 : 0.0;
    default: return std::numeric_limits<double>::quiet_NaN();
  }
}
